function showText(title:string,content:string,meta=''):void{textDialog.innerHTML=`<div class="dialog-header"><h2 id="text-title">${escape(title)}</h2><button data-action="close-text">${t('close')}</button></div><pre class="text-content" tabindex="0"></pre><p class="text-meta">${escape(meta)}</p>`;textDialog.querySelector('pre')!.textContent=content;if(!textDialog.open)textDialog.showModal();}
