function coveragePanel():string{
 const progress=coverageSummary(coverage,new Set(catalog.map((doc)=>doc.id)));
 if(!progress.total&&!catalogIssues.length)return `<p class="notice">${t('noMap')}</p>`;
 return `<section class="coverage-panel" aria-label="${t('coverage')}"><div><strong>${t('coverage')}</strong><span>${progress.covered} / ${progress.total} ${t('covered')} · ${progress.partial} ${t('partial')} · ${progress.planned} ${t('planned')} · ${progress.deferred} ${t('deferred')}</span></div><p>${t('coverageNote')}</p>${progress.missing.length?`<details class="warning"><summary>${t('missing')} · ${progress.missing.length}</summary><ul>${progress.missing.map((id)=>`<li>${escape(id)}</li>`).join('')}</ul></details>`:''}${catalogIssues.length?`<details class="warning"><summary>${t('errors')} · ${catalogIssues.length}</summary><ul>${catalogIssues.map((issue)=>`<li>${escape(issue.document??'')} · ${escape(issue.code)} <span>${escape(issue.message)}</span></li>`).join('')}</ul></details>`:''}${progress.partial+progress.planned+progress.missing.length?`<button data-action="resume">${t('resume')}</button>`:''}</section>`;
}
function filterOptions(values:string[],selected:string,translate=false):string{return [...new Set(values)].sort().map((value)=>`<option value="${escape(value)}" ${selected===value?'selected':''}>${escape(translate?typeLabel(value):value)}</option>`).join('');}
