 $('#workspace').innerHTML=`<section class="intro"><div class="eyebrow">${collectionTitle()}</div><h1>${collection==='wiki'?t('intro'):collectionTitle()}</h1><p>${t('subtitle')}</p></section>${collection==='wiki'?coveragePanel():''}<div class="toolbar"><label class="search"><input id="query" type="search" value="${escape(state.query)}" placeholder="${t('search')}" aria-label="${t('search')}"></label><select id="repo-filter" aria-label="${t('allRepos')}"><option value="">${t('allRepos')}</option>${filterOptions(catalog.flatMap((doc)=>doc.repositories),state.repo)}</select><select id="type-filter" aria-label="${t('allTypes')}"><option value="">${t('allTypes')}</option>${filterOptions(catalog.filter((doc)=>doc.collection===collection).map((doc)=>doc.type),state.type,true)}</select><select id="freshness-filter" aria-label="${t('allStates')}"><option value="">${t('allStates')}</option>${['current','stale','unverified','missing-source','conflict'].map((value)=>`<option value="${value}" ${state.freshness===value?'selected':''}>${t(value)}</option>`).join('')}</select><div class="view-toggle"><button data-view="grid" aria-pressed="${view==='grid'}">${t('grid')}</button><button data-view="list" aria-pressed="${view==='list'}">${t('list')}</button></div></div><p class="result-count" id="result-count" role="status"></p><div id="cards" class="cards ${view==='list'?'list':''}" aria-live="polite"></div>`;
